class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        # 最大堆, 所以存储 (-num, i)
        # 堆顶是heap[0]
        heap = []
        result = []
        for i, num in enumerate(nums):
            heapq.heappush(heap, (-num, i))
            if i >= k - 1:
                # 已存入长度为k的元素
                # 窗口应该是 [i - k + 1, i] 这k个元素
                while heap and heap[0][1] <= i - k:
                    heapq.heappop(heap)
                result.append(-heap[0][0])
        return result
